<?php require_once '../includes/auth.php';require_login();verify_csrf();$u=user();$it=$_POST['institution_type']??$u['institution_type'];$code=$_POST['institution_code']??$u['institution_code'];if(!is_admin()&&!is_sub_officer()){$it=$u['institution_type'];$code=$u['institution_code'];}if($it!=='ashram_shala')exit('Ashram Shala only.');$s=mysqli_prepare($conn,"INSERT INTO students(student_name,student_uid,admission_no,dob,class_name,gender,guardian_name,guardian_contact,address,institution_type,institution_code,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)");mysqli_stmt_bind_param($s,'sssssssssssi',$_POST['student_name'],$_POST['student_uid'],$_POST['admission_no'],$_POST['dob'],$_POST['class_name'],$_POST['gender'],$_POST['guardian_name'],$_POST['guardian_contact'],$_POST['address'],$it,$code,$u['id']);if(!mysqli_stmt_execute($s))exit('Student ID already exists.');log_activity('created','students','Added student');flash('success','Student added.');redirect('students.php');
